{"path": "bowling.py", "content": "class BowlingGame:
    FRAMES = 10
    PINS = 10

    def __init__(self):
        self.rolls = []
        self.frame = 1          # current frame number (1..10)
        self.frame_rolls = []   # rolls in the current frame
        self.complete = False

    def roll(self, pins):
        if self.complete:
            raise IndexError("cannot roll after the game is over")
        if not isinstance(pins, int) or pins < 0:
            raise ValueError("a roll cannot score negative points")
        if pins > self.PINS:
            raise ValueError("a roll cannot score more than 10 points")

        current = self.frame_rolls
        if self.frame < self.FRAMES:
            if current and current[0] + pins > self.PINS:
                raise ValueError("two rolls in a frame cannot score more than 10 points")
            current.append(pins)
            self.rolls.append(pins)
            if pins == self.PINS and len(current) == 1 or len(current) == 2:
                self.frame += 1
                self.frame_rolls = []
            return

        # Tenth frame, including fill balls.
        if len(current) == 1 and current[0] < self.PINS and current[0] + pins > self.PINS:
            raise ValueError("two rolls in a frame cannot score more than 10 points")
        if len(current) == 2:
            first, second = current
            if first == self.PINS and second < self.PINS and second + pins > self.PINS:
                raise ValueError("invalid fill balls: bonus rolls cannot exceed 10 pins")
        current.append(pins)
        self.rolls.append(pins)
        if len(current) == 2 and sum(current) < self.PINS or len(current) == 3:
            self.complete = True

    def score(self):
        if not self.complete:
            raise IndexError("score cannot be taken until the end of the game")
        total = 0
        i = 0
        rolls = self.rolls
        for _ in range(self.FRAMES):
            if rolls[i] == self.PINS:
                total += self.PINS + rolls[i + 1] + rolls[i + 2]
                i += 1
            elif rolls[i] + rolls[i + 1] == self.PINS:
                total += self.PINS + rolls[i + 2]
                i += 2
            else:
                total += rolls[i] + rolls[i + 1]
                i += 2
        return total
"}

